Robotun yönelimi 10°, hedefin açısı 350°. Fark sarılınca ne yazar?

```
float aciFarki(float hedef, float simdiki) {
  float f = hedef - simdiki;
  while (f > 180) f -= 360;
  while (f < -180) f += 360;
  return f;
}

void setup() {
  Serial.begin(9600);
  Serial.println(aciFarki(350, 10), 0);
}

void loop() {}
```
